    private const ROUTES=['/volunteer/verifications','/volunteer/verification','/admin/volunteer-verification'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}
    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user)self::redirect($basePath.'/login');$_SESSION['volunteer_verification_csrf']??=bin2hex(random_bytes(24));
        if($route==='/volunteer/verification'){$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;if(!VolunteerVerificationService::canViewVerification($db,$user,(int)$id)){http_response_code(404);exit('Verification unavailable.');}$v=VolunteerVerificationService::verification($db,(int)$id);self::letter($basePath,$user,$v,isset($_GET['print']));}
        if($route==='/admin/volunteer-verification'){if(!AccessPolicy::canManageVolunteers($user)){http_response_code(403);exit('Volunteer management permission is required.');}if($_SERVER['REQUEST_METHOD']==='POST')self::adminPost($db,$basePath,$user);self::adminPage($db,$basePath,$user);}
        self::memberPage($db,$basePath,$user);
    }
    private static function adminPost(PDO $db,string $basePath,array $user):never
    {
        if(!hash_equals((string)($_SESSION['volunteer_verification_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session token expired.');self::redirect($basePath.'/admin/volunteer-verification');}
        try{
            $action=(string)($_POST['action']??'');$uid=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT)?:0;
            if($action==='issue'){$id=VolunteerVerificationService::issue($db,$user,(int)$uid,(string)($_POST['period_start']??''),(string)($_POST['period_end']??''),trim((string)($_POST['purpose']??''))?:null);self::flash('success','Verified service record issued.');self::redirect($basePath.'/volunteer/verification?id='.$id);}
            elseif($action==='coordinator'){VolunteerVerificationService::assignCoordinator($db,$user,(int)$uid,filter_input(INPUT_POST,'production_id',FILTER_VALIDATE_INT)?:null,(string)($_POST['title']??''),trim((string)($_POST['category']??''))?:null);self::flash('success','Coordinator role assigned.');}
            else throw new RuntimeException('Choose a valid action.');
        }catch(RuntimeException $e){self::flash('error',$e->getMessage());}
        self::redirect($basePath.'/admin/volunteer-verification');
    }
