    {
        $volunteers=VolunteerVerificationService::volunteers($db);$productions=VolunteerVerificationService::productions($db);$u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=self::takeFlash();$subnav=[['label'=>'Shifts','href'=>'/admin/volunteer-shifts','active'=>false],['label'=>'Requirements & training','href'=>'/admin/volunteer-development','active'=>false],['label'=>'Approval queue','href'=>'/admin/volunteer-approvals','active'=>false],['label'=>'Verification','href'=>'/admin/volunteer-verification','active'=>true]];header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Volunteer verification · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/volunteer-verification.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/volunteer-verification',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Volunteer Operations','Service verification & coordinators',$basePath,$subnav);?><div class="vv-page"><?php if($flash):?><div class="vv-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><section class="vv-hero"><small>VERIFIED SERVICE & LEADERSHIP</small><h2>Turn verified work into records people can use.</h2><p>Issue formal service-hour records and maintain explicit coordinator assignments. Individual training, background checks, and eligibility credentials are managed on the person’s Account & Access record.</p></section><div class="vv-grid"><section class="vv-card"><h3>Volunteer readiness belongs with the person</h3><p>Open Account & Access to review or verify an individual volunteer’s background checks, facility education, training, and other eligibility requirements.</p><a class="button" href="<?=$u('/admin/accounts')?>">Open Account & Access</a><a href="<?=$u('/admin/volunteer-development')?>">Manage requirement definitions & training →</a></section><section class="vv-card"><h3>Issue service verification</h3><p>Create a formal snapshot from CTSMD’s verified service ledger for school hours, recognition, or another documented purpose.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_verification_csrf'])?>"><input type="hidden" name="action" value="issue"><label>Volunteer<select name="user_id" required><?php foreach($volunteers as $v):?><option value="<?=(int)$v['id']?>"><?=$e((string)$v['name'])?></option><?php endforeach;?></select></label><label>Start date<input type="date" name="period_start" required></label><label>End date<input type="date" name="period_end" required></label><label>Purpose<input name="purpose" maxlength="190" placeholder="School service hours, recognition…"></label><button class="button" type="submit">Issue verified record</button></form></section><section class="vv-card"><h3>Assign coordinator role</h3><p>Leadership is explicit—it is never inferred from hours worked.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_verification_csrf'])?>"><input type="hidden" name="action" value="coordinator"><label>Volunteer<select name="user_id" required><?php foreach($volunteers as $v):?><option value="<?=(int)$v['id']?>"><?=$e((string)$v['name'])?></option><?php endforeach;?></select></label><label>Coordinator title<input name="title" maxlength="190" required placeholder="Front of House Coordinator"></label><label>Category<input name="category" maxlength="100" placeholder="Front of House"></label><label>Production<select name="production_id"><option value="">CTSMD organization-wide</option><?php foreach($productions as $p):?><option value="<?=(int)$p['id']?>"><?=$e((string)$p['title'])?><?=$p['season']?' · '.$e((string)$p['season']):''?></option><?php endforeach;?></select></label><button class="button" type="submit">Assign coordinator role</button></form></section></div></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }
    private static function memberPage(PDO $db,string $basePath,array $user):never
    {
