v class="vv-record static"><span><b><?=$e((string)$role['title'])?></b><small><?=$role['production_title']?$e((string)$role['production_title']):'CTSMD'?><?=$role['category']?' · '.$e((string)$role['category']):''?></small></span><em><?=$e(ucfirst((string)$role['status']))?></em></div><?php endforeach;?></section></div></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }
    private static function letter(string $basePath,array $user,array $v,bool $print):never
    {
        $u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $x):string=>htmlspecialchars($x,ENT_QUOTES,'UTF-8');header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$e((string)$v['verification_code'])?> · CTSMD Service Verification</title><link rel="stylesheet" href="<?=$u('/assets/css/volunteer-verification.css')?>"></head><body class="vv-letter"><main><header><strong>CHILDREN’S THEATRE OF SOUTHERN MARYLAND</strong><span>Volunteer Service Verification</span></header><h1>Verification of Community Service</h1><p>This record certifies that <b><?=$e((string)$v['volunteer_name'])?></b> completed <b><?=number_format(((int)$v['verified_minutes'])/60,1)?> verified volunteer hours</b> recorded by Children’s Theatre of Southern Maryland between <?=date('F j, Y',strtotime((string)$v['period_start']))?> and <?=date('F j, Y',strtotime((string)$v['period_end']))?>.</p><?php if($v['purpose']):?><p><b>Purpose:</b> <?=$e((string)$v['purpose'])?></p><?php endif;?><section><h2>Verified service</h2><?php foreach($v['snapshot'] as $item):?><div><span><?=date('M j, Y',strtotime((string)$item['served_at']))?> · <?=$e((string)$item['production'])?> · <?=$e((string)$item['shift'])?></span><b><?=number_format(((int)$item['minutes'])/60,1)?>h</b></div><?php endforeach;?></section><footer><p><b>Verified by:</b> <?=$e((string)$v['verifier_name'])?><br><b>Issued:</b> <?=date('F j, Y',strtotime((string)$v['verified_at']))?><br><b>Verification code:</b> <?=$e((string)$v['verification_code'])?></p><p>This document was generated from CTSMD Connect’s verified volunteer service ledger.</p></footer><?php if(!$print):?><div class="vv-letter-actions"><a href="<?=$u('/volunteer/verifications')?>">Back</a><a href="<?=$u('/volunteer/verification?id='.(int)$v['id'].'&print=1')?>" target="_blank">Print / Save PDF</a></div><?php else:?><script>window.addEventListener('load',()=>window.print());</script><?php endif;?></main></body></html><?php exit;
    }
    private static function flash(string $type,string $message):void{$_SESSION['vv_flash']=['type'=>$type,'message'=>$message];}private static function takeFlash():?array{$f=$_SESSION['vv_flash']??null;unset($_SESSION['vv_flash']);return is_array($f)?$f:null;}private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
